import org.objectweb.asm.*;import org.objectweb.asm.tree.*;import org.objectweb.asm.tree.analysis.*;import java.util.*;import java.nio.file.*;import java.util.zip.*;
public class Patch implements Opcodes{
 static int hooks;static final String SETTINGS="dev/zomboid/hordes/SimpleSettings",LOOT="dev/zomboid/hordes/SimpleLoot",PANEL="dev/zomboid/hordes/SimplePanel";
 static MethodInsnNode call(String o,String n,String d){return new MethodInsnNode(INVOKESTATIC,o,n,d,false);}static void check(int n,int want,String msg){if(n!=want)throw new IllegalStateException(msg+" "+n);hooks++;System.out.println(msg);}
 static void clear(MethodNode m){m.instructions.clear();m.tryCatchBlocks.clear();m.localVariables=null;}
 static byte[]patch(byte[]bytes)throws Exception{ClassNode c=new ClassNode();new ClassReader(bytes).accept(c,0);int before=hooks;for(MethodNode m:c.methods){
  if(c.name.equals("dev/zomboid/hordes/ZoneSettings")&&m.name.equals("install")){int n=0;for(AbstractInsnNode a:m.instructions.toArray())if(a.getOpcode()==RETURN){InsnList x=new InsnList();for(int i=0;i<4;i++)x.add(new VarInsnNode(ALOAD,i));x.add(call(SETTINGS,"install","(Ljava/util/Map;Ljava/util/Map;Ljava/util/Map;Ljava/util/Map;)V"));m.instructions.insertBefore(a,x);n++;}check(n,1,"complete server/client settings schema");}
  if(c.name.equals("dev/zomboid/hordes/ApocalypseSettings")&&m.name.equals("preset")){int n=0;for(AbstractInsnNode a:m.instructions.toArray())if(a.getOpcode()==RETURN){InsnList x=new InsnList();x.add(new VarInsnNode(ALOAD,0));x.add(new VarInsnNode(ILOAD,1));x.add(call(SETTINGS,"afterPreset","(Ljava/util/Map;I)V"));m.instructions.insertBefore(a,x);n++;}check(n,1,"all five profiles change actual generation controls");}
  if(c.name.equals("dev/zomboid/hordes/WorldTuning")&&m.name.equals("batch")){InsnList x=new InsnList();x.add(new VarInsnNode(ALOAD,0));x.add(call(SETTINGS,"normalize","(Ljava/util/Map;)V"));m.instructions.insert(x);check(1,1,"advanced aliases update authoritative corpse controls");}
  if(c.name.equals("dev/zomboid/hordes/PanelLootAuthority")){
   if(m.name.equals("container")||m.name.equals("body")){clear(m);for(int i=0;i<3;i++)m.instructions.add(new VarInsnNode(ALOAD,i));m.instructions.add(call(LOOT,m.name,m.desc));m.instructions.add(new InsnNode(m.name.equals("body")?IRETURN:ARETURN));m.maxLocals=3;m.maxStack=3;check(1,1,"server generation path "+m.name);}
   if(m.name.equals("capture")){int n=0;for(AbstractInsnNode a:m.instructions.toArray())if(a.getOpcode()==RETURN){InsnList x=new InsnList();x.add(new VarInsnNode(ALOAD,0));x.add(call(PANEL,"capture","(Ljava/lang/Object;)V"));m.instructions.insertBefore(a,x);n++;}check(n,1,"client snapshot records saved values");}
  }
  if(c.name.equals("dev/zomboid/hordes/AdminNetwork")&&m.name.equals("register")){int n=0;for(AbstractInsnNode a:m.instructions)if(a instanceof LdcInsnNode l&&l.cst instanceof String s&&s.matches("[0-9]+")){l.cst="40";n++;}check(n,1,"matching network version 40");}
  if(c.name.equals("dev/zomboid/hordes/client/LootPreviewScreen")&&m.name.equals("render")){LabelNode original=new LabelNode();InsnList x=new InsnList();x.add(new VarInsnNode(ALOAD,0));x.add(call(PANEL,"newPreview","(Ljava/lang/Object;)Z"));x.add(new JumpInsnNode(IFEQ,original));x.add(new VarInsnNode(ALOAD,0));x.add(new VarInsnNode(ALOAD,1));x.add(call(PANEL,"previewRender","(Ljava/lang/Object;Ljava/lang/Object;)V"));x.add(new VarInsnNode(ALOAD,0));x.add(new VarInsnNode(ALOAD,1));x.add(new VarInsnNode(ILOAD,2));x.add(new VarInsnNode(ILOAD,3));x.add(new VarInsnNode(FLOAD,4));x.add(new MethodInsnNode(INVOKESPECIAL,c.superName,"render",m.desc,false));x.add(new InsnNode(RETURN));x.add(original);x.add(new FrameNode(F_SAME,0,null,0,null));m.instructions.insert(x);check(1,1,"advanced preview no longer simulates obsolete ten-stack weighted rules");}
  if(c.name.equals("dev/zomboid/hordes/client/AdminScreen")){
   if(m.name.equals("<clinit>")){int n=0;for(AbstractInsnNode a:m.instructions.toArray())if(a.getOpcode()==RETURN){InsnList x=new InsnList();for(String key:new String[]{"LABELS","HINTS"}){x.add(new FieldInsnNode(GETSTATIC,c.name,key,"[[Ljava/lang/String;"));x.add(new LdcInsnNode(key));x.add(call(PANEL,"advancedRows","([[Ljava/lang/String;Ljava/lang/String;)[[Ljava/lang/String;"));x.add(new FieldInsnNode(PUTSTATIC,c.name,key,"[[Ljava/lang/String;"));}m.instructions.insertBefore(a,x);n++;}check(n,1,"advanced hints describe actual direct probabilities");}
   if(m.name.equals("init")){LabelNode original=new LabelNode();InsnList x=new InsnList();x.add(new VarInsnNode(ALOAD,0));x.add(call(PANEL,"init","(Ljava/lang/Object;)Z"));x.add(new JumpInsnNode(IFEQ,original));x.add(new InsnNode(RETURN));x.add(original);x.add(new FrameNode(F_SAME,0,null,0,null));m.instructions.insert(x);check(1,1,"simple screen default with explicit advanced escape");}
   if(m.name.equals("render")){LabelNode original=new LabelNode();InsnList x=new InsnList();x.add(new VarInsnNode(ALOAD,0));x.add(call(PANEL,"basic","(Ljava/lang/Object;)Z"));x.add(new JumpInsnNode(IFEQ,original));x.add(new VarInsnNode(ALOAD,0));x.add(new VarInsnNode(ALOAD,1));x.add(call(PANEL,"render","(Ljava/lang/Object;Ljava/lang/Object;)V"));x.add(new VarInsnNode(ALOAD,0));x.add(new VarInsnNode(ALOAD,1));x.add(new VarInsnNode(ILOAD,2));x.add(new VarInsnNode(ILOAD,3));x.add(new VarInsnNode(FLOAD,4));x.add(new MethodInsnNode(INVOKESPECIAL,c.superName,"render",m.desc,false));x.add(new InsnNode(RETURN));x.add(original);x.add(new FrameNode(F_SAME,0,null,0,null));m.instructions.insert(x);check(1,1,"simple render uses native widget rendering and tooltips");}
   if(m.name.equals("mouseScrolled")){LabelNode original=new LabelNode();InsnList x=new InsnList();x.add(new VarInsnNode(ALOAD,0));x.add(call(PANEL,"basic","(Ljava/lang/Object;)Z"));x.add(new JumpInsnNode(IFEQ,original));x.add(new InsnNode(ICONST_0));x.add(new InsnNode(IRETURN));x.add(original);x.add(new FrameNode(F_SAME,0,null,0,null));m.instructions.insert(x);check(1,1,"basic wheel cannot alter hidden advanced controls");}
  }
 }
 if(hooks==before)return bytes;ClassWriter w=new ClassWriter(ClassWriter.COMPUTE_MAXS);c.accept(w);ClassNode v=new ClassNode();new ClassReader(w.toByteArray()).accept(v,0);for(MethodNode m:v.methods)if((m.access&(ACC_NATIVE|ACC_ABSTRACT))==0)new Analyzer<BasicValue>(new BasicVerifier()).analyze(v.name,m);return w.toByteArray();}
 public static void main(String[]a)throws Exception{Map<String,byte[]>entries=new TreeMap<>();try(ZipFile z=new ZipFile(a[0])){for(ZipEntry e:Collections.list(z.entries())){byte[]b=z.getInputStream(e).readAllBytes();entries.put(e.getName(),e.getName().endsWith(".class")?patch(b):b);}}try(var files=Files.walk(Path.of(a[2]))){for(Path p:files.filter(p->p.toString().endsWith(".class")).toList())entries.put(Path.of(a[2]).relativize(p).toString(),Files.readAllBytes(p));}if(hooks!=12)throw new IllegalStateException("total "+hooks);try(ZipOutputStream z=new ZipOutputStream(Files.newOutputStream(Path.of(a[1])))){for(var e:entries.entrySet()){ZipEntry n=new ZipEntry(e.getKey());n.setTime(0);z.putNextEntry(n);z.write(e.getValue());z.closeEntry();}}}
}
